// On-device feature extraction (3-grams) - illustrative
function extractFeatures(text) {
  const t = text.toLowerCase();
  const grams = {}; 
  for (let i = 0; i < t.length - 2; i++) {
    const g = t.slice(i, i + 3);
    grams[g] = (grams[g] || 0) + 1;
  }
  return grams;
}
```

